local TweenService = game:GetService("TweenService")
local Camera = workspace.CurrentCamera
local class = require(script.Parent.Parent.apis.class)
local BaseComponent = require(script.Parent.Parent.apis.BaseComponent)
local module = class(script.Name, BaseComponent)

function module:ctor(element)
    self._anims = {}
	self.super.ctor(self, element)
end

function module:RotateBy(speed)
    local t = 360 / speed
    local element: GuiObject = self._element
    if element:IsA("GuiObject") then
        local anim = TweenService:Create(element, TweenInfo.new(t, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1), {Rotation = element.Rotation + 360})
        anim:Play()
        table.insert(self._anims, anim)
    end
end

function module:StopAll()
    for _, anim in ipairs(self._anims) do
        anim:Cancel()
    end
    self._anims = {}
end

return module